mapper.select:
SELECT r.org_unit_id AS unitId, ek.year, ek.period_code AS period, k.id AS kpiId, k.code AS kpiCode, k.name AS kpiName, k.is_focus AS isFocus,
  pe.id AS perspectiveId, pe.name AS perspectiveName, pe.color AS perspectiveColor, pe.sort_order AS perspectiveSort, uom.name AS unitOfMeasureName,
  r.plan_value AS planValue, r.year_plan_value AS yearPlanValue, r.final_result AS finalResult, r.completion_rate AS completionRate,
  r.year_completion_rate AS yearCompletionRate, r.score, r.bsc_score AS bscScore, r.rating, r.status, r.updated_at AS updatedAt
FROM evaluation_result r JOIN evaluation_kpi ek ON ek.id = r.evaluation_kpi_id JOIN kpi k ON k.id = ek.kpi_id
  JOIN perspective pe ON pe.id = k.perspective_id LEFT JOIN unit_of_measure uom ON uom.id = k.unit_of_measure_id
WHERE r.deleted = 0 AND k.parent_id IS NULL
  AND r.org_unit_id IN #{u}
  AND ek.year IN #{y}
  AND ek.period_code = #{period}
  AND k.id = #{kpiId}
  AND k.is_focus = 1
ORDER BY pe.sort_order, k.code

SELECT MAX(r.updated_at) FROM evaluation_result r JOIN evaluation_kpi ek ON ek.id = r.evaluation_kpi_id
WHERE r.deleted = 0 AND (r.final_result IS NOT NULL OR r.score IS NOT NULL)
  AND r.org_unit_id IN #{u}
  AND ek.year IN #{y}
  AND ek.period_code = #{period}

SELECT  FROM bsc_unit_summary s JOIN org_unit o ON o.id = s.org_unit_id
WHERE o.deleted = 0
  AND s.org_unit_id IN #{u}
  AND s.rank_group = #{rankGroup}
  AND o.parent_id = #{parentId}
  AND s.year IN #{y}
  AND s.period_code = #{period}
ORDER BY s.year, FIELD(s.period_code, 'Q1', 'Q2', 'H1', 'Q3', 'Q4', 'Y'), COALESCE(s.rank_in_group, 9999), o.sort_order, o.code
